module radix2_div (
    input wire clk,
    input wire rst,
    input wire [7:0] dividend,
    input wire [7:0] divisor,
    input wire sign,
    input wire opn_valid,
    output reg res_valid,
    input wire res_ready,
    output wire [15:0] result
);

wire [7:0] abs_dividend, abs_divisor;
wire [15:0] partial_result;
reg [15:0] SR;
reg [7:0] NEG_DIVISOR;
reg [3:0] cnt;
reg start_cnt;
reg [15:0] dividend_extended;
reg [15:0] divisor_extended;
reg div_sign, div_sign_d;
reg opn_valid_d;

always @(posedge clk or posedge rst) begin
    if(rst) begin
        opn_valid_d <= 0;
        div_sign <= 0;
        div_sign_d <= 0;
    end
    else begin
        opn_valid_d <= opn_valid;
        div_sign <= sign;
        div_sign_d <= div_sign;
    end
end
assign abs_dividend = (div_sign_d && (dividend != 0)) ? (~dividend + 1) : dividend;
assign abs_divisor = (div_sign_d && (divisor != 0)) ? (~divisor + 1) : divisor;
assign result = (div_sign_d && ((dividend > 0 || divisor == 0))) ? ~SR + 1 : SR;
assign res_valid = rst ? 0 : (cnt[3] ? 1 : (opn_valid_d & ~res_valid) ? 1 : (res_valid & opn_valid_d) ? 0 : res_valid);
assign partial_result = {{8{~cnt[3]}}, abs_dividend << 1};
always @(posedge clk or posedge rst) begin
    if (rst) begin
        SR <= 16'b0;
        NEG_DIVISOR <= 16'b0;
        cnt <= 0;
        start_cnt <= 0;
    end else begin
        if (opn_valid_d && !res_valid) begin
            SR <= {abs_dividend, 8'b0}; 
            NEG_DIVISOR <= (~abs_divisor + 1); 
            cnt <= 1;
            start_cnt <= 1;
        end else if (start_cnt) begin
            if (cnt[3]) begin
                start_cnt <= 0;
                cnt <= 0;
                SR <= {partial_result[15:8] + partial_result[7], partial_result[7:0]};
            end else begin
                cnt <= cnt + 1;
                if (partial_result[15:8] >= abs_divisor) begin
                    SR <= {partial_result[15:8] - abs_divisor, partial_result[7:0], 1'b1};
                end else begin
                    SR <= {partial_result[15:8], partial_result[7:0], 1'b0};
                end
            end
        end
    end
end
endmodule
